{"path": "projects/wordcount-py/app/wordcount.py", "content": "#!/usr/bin/env python3
"""wordcount.py FILE -- print the line, word and character counts of FILE, like wc."""
import sys


def count(text):
    """Return (lines, words, chars) for text, counted the way wc -l/-w/-m do."""
    return text.count("\n"), len(text.split()), len(text)


def main(argv):
    if len(argv) != 2:
        print("usage: wordcount.py FILE", file=sys.stderr)
        return 2
    path = argv[1]
    try:
        with open(path, encoding="utf-8", newline="") as f:
            text = f.read()
    except OSError as e:
        print("wordcount.py: %s: %s" % (path, e.strerror), file=sys.stderr)
        return 1
    lines, words, chars = count(text)
    print("%d %d %d %s" % (lines, words, chars, path))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
"}

{"path": "projects/wordcount-py/app/test_wordcount.py", "content": "import os
import subprocess
import sys
import tempfile
import unittest

import wordcount

HERE = os.path.dirname(os.path.abspath(__file__))
SCRIPT = os.path.join(HERE, "wordcount.py")


class CountTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(wordcount.count(""), (0, 0, 0))

    def test_no_trailing_newline(self):
        self.assertEqual(wordcount.count("one two\nthree"), (1, 3, 13))

    def test_multiple_spaces_and_tabs(self):
        self.assertEqual(wordcount.count("a   b\t\tc  \n"), (1, 3, 12))

    def test_unicode_counts_characters_not_bytes(self):
        self.assertEqual(wordcount.count("café\n"), (1, 1, 5))


class CliTests(unittest.TestCase):
    def run_cli(self, *args):
        return subprocess.run([sys.executable, SCRIPT, *args],
                              capture_output=True, text=True)

    def test_file(self):
        with tempfile.NamedTemporaryFile("w", suffix=".txt", delete=False,
                                         encoding="utf-8") as f:
            f.write("hello world\nbye\n")
        try:
            r = self.run_cli(f.name)
            self.assertEqual(r.returncode, 0)
            self.assertEqual(r.stdout, "2 3 16 %s\n" % f.name)
        finally:
            os.unlink(f.name)

    def test_missing_file(self):
        r = self.run_cli(os.path.join(HERE, "does-not-exist.txt"))
        self.assertNotEqual(r.returncode, 0)
        self.assertIn("No such file", r.stderr)
        self.assertEqual(r.stdout, "")

    def test_no_argument(self):
        r = self.run_cli()
        self.assertNotEqual(r.returncode, 0)
        self.assertIn("usage", r.stderr)


if __name__ == "__main__":
    unittest.main()
"}
